update public.zbiorniki set r = 'Obowiązuje regulamin łowiska umieszczony na tablicy. Łowisko NO-KILL — zakaz zabierania ryb (sum wg zasad ogólnych). Tylko w dzień (godzina kalendarzowa); zakaz połowu w porze nocnej na stawach nr 1 i 2. Zakaz łodzi i brodzenia (łódki zdalnie sterowane do zanęt dozwolone). Mata, podbierak, haki bezzadziorowe. Zakaz przechowywania ryb w siatkach; zakaz zbyt długiego przetrzymywania ryb bez wody. Staw 1: zakaz metody gruntowej.' where n = 'Rzemień — Stawy 1 i 2';

update public.zbiorniki set r = 'Zb. 1: NO-KILL, tylko w dzień, zakaz brodzenia, zakaz sprzętu pływającego (łódki zdalnie sterowane do zanęt dozwolone), mata (nie dot. metody muchowej i spinningowej), podbierak, haki bezzadziorowe. Zb. 2-3: zakaz sprzętu pływającego (jw.), zakaz kąpieli, bojki tylko markery połączone z wędziskiem, zakaz ognisk, szczupak powyżej 75 cm wraca do wody.' where n = 'Świętoniowa';

do $$
declare gor_count int; begin
  select count(*) into gor_count from public.rivers where c = 'gor';
  raise notice 'Odcinków krainy pstrąga: % (oczekiwane 18)', gor_count;
end $$;

commit;
